import numpy as np

def find_rectangles_debug(grid):
    """Find all hollow rectangles in the grid"""
    n, m = grid.shape
    rects = []

    for i in range(n):
        for j in range(m):
            if grid[i, j] == 4:
                # Find max rectangle with (i,j) as top-left corner
                r1, c1 = i, j

                # Expand vertically to find bottom
                r2 = i
                for rr in range(i+1, n):
                    if grid[rr, j] == 4:
                        r2 = rr
                    else:
                        break
                if r2 == i:
                    continue

                # Expand horizontally to find right
                c2 = j
                for cc in range(j+1, m):
                    if grid[i, cc] == 4:
                        c2 = cc
                    else:
                        break
                if c2 == j:
                    continue

                # Check if we have a proper rectangle
                if r2 == r1 or c2 == c1:
                    continue

                height = r2 - r1 + 1
                width = c2 - j + 1
                if height < 3 or width < 3:
                    continue

                rect = (r1, c1, r2, c2)

                # Check if all four corners are 4
                corners = [(r1, c1), (r1, c2), (r2, c1), (r2, c2)]
                all_corners_4 = all(grid[r, c] == 4 for r, c in corners)
                print(f"Potential rect: {rect}, corners: {all_corners_4}")
                if all_corners_4:
                    rects.append(rect)

    return rects

