import numpy as np

def is_hollow_rectangle(grid, r1, c1, r2, c2):
    """Check if the bounding box forms a hollow rectangle outline"""
    n, m = grid.shape
    # Check bounds
    if r1 >= r2 or c1 >= c2:
        return False

    # Check top and bottom edges
    for c in range(c1, c2 + 1):
        if grid[r1, c] != 4 or grid[r2, c] != 4:
            return False

    # Check left and right edges
    for r in range(r1, r2 + 1):
        if grid[r, c1] != 4 or grid[r, c2] != 4:
            return False

    # Check that interior is empty (not all filled)
    if r2 > r1 + 1 and c2 > c1 + 1:
        for r in range(r1 + 1, r2):
            for c in range(c1 + 1, c2):
                if grid[r, c] == 4:
                    return False  # Not hollow - fully filled

    return True

def fill_hollow_rectangles(grid):
    """Fill in the interior of hollow rectangles"""
    grid = np.array(grid).copy()
    n, m = grid.shape

    # Find all bounding boxes of components
    visited = np.zeros((n, m), dtype=bool)

    for i in range(n):
        for j in range(m):
            if grid[i, j] == 4 and not visited[i, j]:
                # BFS to find component
                cells = []
                queue = [(i, j)]
                visited[i, j] = True

                while queue:
                    r, c = queue.pop(0)
                    cells.append((r, c))

                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr, nc] == 4 and not visited[nr, nc]:
                                visited[nr, nc] = True
                                queue.append((nr, nc))

                if len(cells) > 1:
                    rows = [r for r, c in cells]
                    cols = [c for r, c in cells]
                    r1, r2 = min(rows), max(rows)
                    c1, c2 = min(cols), max(cols)

                    # Check if it's a hollow rectangle
                    if is_hollow_rectangle(grid, r1, c1, r2, c2):
                        # Fill interior
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                grid[r, c] = 4

    return grid

